    """
    Takes a list of dict rows (each with 'region' and 'revenue') and returns 
    a dict mapping region to total revenue as a float, ignoring invalid rows.
    """
    regional_revenue = {}
    for row in rows:
        region = row.get('region')
        revenue = row.get('revenue')

        if region is None:
            continue

        try:
            # Handle both numeric types and strings
            if isinstance(revenue, str):
                revenue_float = float(revenue)
            elif isinstance(revenue, (int, float)):
                revenue_float = float(revenue)
            else:
                continue # Missing or unsupported type

            regional_revenue[region] = regional_revenue.get(region, 0.0) + revenue_float
        except (ValueError, TypeError):
            # Ignore rows with unparseable revenue
            continue

    return regional_revenue

