import pytest
from summarize import summarize

def test_basic_sum():
    rows = [
        {'region': 'North', 'revenue': 100.5},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': 50}
    ]
    expected = {'North': 150.5, 'South': 200.0}
    assert summarize(rows) == expected

def test_empty_input():
    assert summarize([]) == {}

def test_missing_keys():
    rows = [
        {'region': 'A', 'revenue': 10},
        {'region': 'B'},  # Missing revenue
        {'revenue': 5}     # Missing region
    ]
    expected = {'A': 10.0}
    assert summarize(rows) == expected

def test_unparseable_revenue():
    rows = [
        {'region': 'A', 'revenue': 10},
        {'region': 'B', 'revenue': 'invalid'},
        {'region': 'A', 'revenue': '20.5'}, # String that is parseable
        {'region': 'C', 'revenue': None}
    ]
    # Expected: A = 10 + 20.5, B is ignored, C is ignored
    expected = {'A': 30.5}
    assert summarize(rows) == expected

def test_mixed_types():
    rows = [
        {'region': 'Mid', 'revenue': 100},
        {'region': 'Mid', 'revenue': '200.5'},
        {'region': 'Mid', 'revenue': 'not a number'} # Ignored
    ]
    assert summarize(rows) == {'Mid': 300.5}

def test_large_numbers():
    rows = [
        {'region': 'Global', 'revenue': 1000000},
        {'region': 'Global', 'revenue': 50000}
    ]
    assert summarize(rows) == {'Global': 1050000.0}

